// === Validate brand check submission ===
// The client holds no secret, so trust is earned here instead:
//   1. honeypot must be empty (bots fill it)
//   2. submission must not be implausibly fast
//   3. browser Origin (when present) must be one of ours
//   4. all fields present, email is a business domain
//   5. global rate limit, plus a repeat flag for the Slack alert
// Blocked submissions still get a 200 OK so bots learn nothing.
// ENFORCE = true blocks. While false, nothing is blocked (tags only).

const ENFORCE = true;
const MIN_ELAPSED_MS = 8000; // discovery theatre alone takes ~4.2s
const MAX_PER_HOUR = 30;

const ALLOWED_ORIGINS = new Set([
  'https://www.geeiq.com',
  'https://geeiq.com',
  'https://check.geeiq.com',
  'http://localhost:5173',
  'http://localhost:4173',
]);

// Same list as the Framer Demo Form workflow (free, personal, disposable):
const BLOCKED_EMAIL_DOMAINS = new Set([
  'gmail.com','googlemail.com','yahoo.com','yahoo.co.uk','ymail.com','rocketmail.com',
  'hotmail.com','hotmail.co.uk','outlook.com','live.com','live.co.uk','msn.com',
  'icloud.com','me.com','mac.com','aol.com','gmx.com','gmx.net','gmx.co.uk','mail.com',
  'proton.me','protonmail.com','pm.me','yandex.com','yandex.ru','zoho.com',
  'hey.com','fastmail.com','tutanota.com','qq.com','163.com','126.com',
  'mailinator.com','guerrillamail.com','10minutemail.com','tempmail.com','temp-mail.org',
  'dosbee.com','trashmail.com','getnada.com','yopmail.com','sharklasers.com','throwawaymail.com'
]);

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const item = $input.first();
const headers = item.json.headers || {};
const body = item.json.body || {};
const s = (v) => (v || '').toString().trim();

const brand = s(body.brand).slice(0, 120);
const firstName = s(body.firstName).slice(0, 80);
const lastName = s(body.lastName).slice(0, 80);
const jobTitle = s(body.jobTitle).slice(0, 120);
const email = s(body.email).toLowerCase();
const domain = email.includes('@') ? email.split('@').pop() : '';

let blockReason = null;
if (s(body.hp)) blockReason = 'honeypot_filled';
else if (typeof body.elapsedMs === 'number' && body.elapsedMs < MIN_ELAPSED_MS) blockReason = 'submitted_too_fast';
else if (headers.origin && !ALLOWED_ORIGINS.has(headers.origin)) blockReason = 'unknown_origin';
else if (!brand || !firstName || !lastName || !jobTitle) blockReason = 'missing_fields';
else if (!EMAIL_RE.test(email)) blockReason = 'bad_email_format';
else if (!domain || BLOCKED_EMAIL_DOMAINS.has(domain)) blockReason = 'non_business_email';

// Rate limit and repeat flag. Static data persists between production
// executions only, so test runs in the editor are never rate limited.
const sd = $getWorkflowStaticData('global');
const now = Date.now();
sd.recent = (sd.recent || []).filter((t) => now - t < 3600000);
if (!blockReason && sd.recent.length >= MAX_PER_HOUR) blockReason = 'rate_limited';
if (!blockReason) sd.recent.push(now);
sd.byEmail = sd.byEmail || {};
for (const k of Object.keys(sd.byEmail)) {
  if (now - sd.byEmail[k] > 86400000) delete sd.byEmail[k];
}
const repeat = !!sd.byEmail[email];
if (!blockReason) sd.byEmail[email] = now;

return [{
  json: {
    _passed: ENFORCE ? blockReason === null : true,
    _blockReason: blockReason,
    brand,
    firstName,
    lastName,
    jobTitle,
    email,
    pageUrl: s(body.pageUrl).slice(0, 300),
    elapsedMs: typeof body.elapsedMs === 'number' ? body.elapsedMs : null,
    submittedAt: s(body.submittedAt),
    repeat,
  },
}];

