parameters.jsCode:
const v = $('Validate submission').first().json;
const res = $input.first().json;
const contactId = res.results && res.results[0] ? String(res.results[0].id) : '';
const hubspotUrl = contactId
  ? `https://app.hubspot.com/contacts/5878363/record/0-1/${contactId}`
  : 'https://app.hubspot.com/contacts/5878363';
return [{ json: { ...v, contactId, hubspotUrl } }];

